-- Timed business configuration from MasterData_RegionTw_Production.bytes.
-- Source bundle a3420859ca359a49fd29dda1db0b97b1; same source as migration 007_home_costume_scenes.sql.
CREATE TABLE public.game_time_definitions (
    name TEXT PRIMARY KEY,
    data JSONB NOT NULL CHECK(jsonb_typeof(data) = 'array')
);
CREATE TABLE public.player_time_state (
    player_id TEXT PRIMARY KEY REFERENCES public.players ON DELETE CASCADE,
    last_login_day BIGINT,
    checked_at BIGINT NOT NULL DEFAULT 0
);
CREATE TABLE public.player_accumulates (
    player_id TEXT NOT NULL REFERENCES public.players ON DELETE CASCADE,
    code BIGINT NOT NULL, count BIGINT NOT NULL CHECK(count >= 0),
    count_up_at BIGINT NOT NULL, period BIGINT NOT NULL,
    PRIMARY KEY(player_id, code)
);
CREATE TABLE public.mission_receipts (
    player_id TEXT NOT NULL REFERENCES public.players ON DELETE CASCADE,
    mission_code BIGINT NOT NULL, period BIGINT NOT NULL, received_at BIGINT NOT NULL,
    PRIMARY KEY(player_id, mission_code, period)
);
CREATE TABLE public.login_bonus_progress (
    player_id TEXT NOT NULL REFERENCES public.players ON DELETE CASCADE,
    bonus_code BIGINT NOT NULL, next_index INTEGER NOT NULL DEFAULT 0,
    last_day BIGINT, PRIMARY KEY(player_id, bonus_code)
);
CREATE TABLE public.player_battle_passes (
    player_id TEXT NOT NULL REFERENCES public.players ON DELETE CASCADE,
    code BIGINT NOT NULL, total_point INTEGER NOT NULL DEFAULT 0,
    normal_received_level INTEGER NOT NULL DEFAULT 0, special_received_level INTEGER NOT NULL DEFAULT 0,
    weekly_point INTEGER NOT NULL DEFAULT 0, weekly_received_at BIGINT NOT NULL,
    is_purchased BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY(player_id, code)
);
CREATE TABLE public.player_shop_passes (
    player_id TEXT NOT NULL REFERENCES public.players ON DELETE CASCADE,
    code BIGINT NOT NULL, activated_at BIGINT NOT NULL, end_at BIGINT NOT NULL,
    notified_at BIGINT, last_reward_day BIGINT,
    PRIMARY KEY(player_id, code), CHECK(end_at > activated_at)
);
