INSERT INTO public.game_time_definitions(name,data) VALUES ('shop_pass_master','[{"Code":100001,"Name":"每日幻魔石通行證","Description":"立刻獲得800個付費幻魔石，\n且30天內每天都可以獲得100個免費幻魔石。\n當有效期限短於3天時，即可再次購買。","ContinueDays":30,"RepurchaseDays":3,"RewardCodes":[101004]},{"Code":100002,"Name":"每日體力通行證","Description":"立刻獲得384個付費幻魔石，且7天內每天都可以獲得6個「鮪當勞」漢堡。\n可再次購買，但有效期限長於30天時無法購買。","ContinueDays":7,"RepurchaseDays":23,"RewardCodes":[103006]}]'::jsonb);
